        if schema is not None:
            loads_kwargs["schema"] = schema
        parsed_json = loads(malformed_json, **loads_kwargs)

        return jsonify(parsed_json)
    except (BadRequest, TypeError, ValueError) as e:
        return jsonify({"error": str(e)}), 400


