    """
    Return True when the current '(' wraps exactly one JSON value, like ``(1)``, ``("x")`` or ``([1, 2])``.

    Text that is not a JSON value, like ``(some clarification)",` is not a grouped value. Repairing it as
    one would let the parser swallow the text around the parentheses (and everything up to the next quote).
    """
    n: int = len(self.json_str)
    start: int = self.index + self.scroll_whitespaces(idx=1)
    if start >= n:
        return False
    char: str = self.json_str[start]
    end: int = start

    if char in STRING_DELIMITERS:
        end = start + 1
        while end < n and self.json_str[end] != char:
            end += 2 if self.json_str[end] == "\\" else 1
