                if inner == "\\":
                    end += 2
                    continue
                if inner == quote:
                    quote = None
            elif inner in STRING_DELIMITERS:
                quote = inner
            elif inner in "([{":
                depth += 1
            elif inner in ")]}":
                depth -= 1
                if depth == 0:
                    break
