class DocumentScopedValidator:
    """Validate a sub schema in the reference scope of the root schema document.

    A sub schema (for example one branch of an `anyOf`) does not carry the `$defs`
    of the document it belongs to, so validating it as a standalone schema would
    break root relative references such as `#/$defs/Example`. Validating through
    the root document validator keeps those references resolvable.
    """

    def __init__(self, document_validator: Any, schema: dict[str, Any]) -> None:
        self._document_validator = document_validator
        self.schema = schema

    def _iter_errors(self, value: JSONReturnType) -> Any:
        return self._document_validator.descend(value, schema=self.schema)

    def is_valid(self, value: JSONReturnType) -> bool:
        return next(self._iter_errors(value), None) is None

    def validate(self, value: JSONReturnType) -> None:
        error = next(self._iter_errors(value), None)
        if error is not None:
            raise error


