def _prompt_text(text: str, err: bool) -> str:
    """Return the prompt *text* with ANSI styles applied or removed the
    same way :func:`~click.echo` does for its message.

    The prompt is written to ``<stderr>`` when ``err`` is set, otherwise to
    ``<stdout>``, so those are the streams used to decide if ANSI codes have
    to be stripped. This keeps ``prompt``, ``confirm`` and friends in sync
    with ``echo``: styles are kept for a terminal and stripped otherwise.
    """
    stream = sys.stderr if err else sys.stdout

    if should_strip_ansi(stream, resolve_color_default(None)):
        return strip_ansi(text)

    return text


def _readline_prompt(func: t.Callable[[str], str], text: str, err: bool) -> str:
    """Call a prompt function, passing the full prompt on non-Windows so
    readline can handle line editing and cursor positioning correctly.

    ANSI codes are removed from the prompt if the stream it is written to
    does not support them, matching the behavior of :func:`~click.echo`.
    """
    text = _prompt_text(text, err)

    if err:
        with redirect_stdout(sys.stderr):
            return func(text)

    return func(text)

