def get_class_member(cls: type, attrname: str) -> tuple[bool, Any]:
    """
    Look up a member on a class object, as it would be seen through its instances.

    Members which are only available on the instances of the class (methods,
    properties, slots and attributes only annotated in the class body) cannot be
    accessed on the class object itself, in which case only their presence is reported,
    and their value is returned as :data:`.unset`.

    :return: ``True`` and the value of the member if it could be accessed on the class
        object, or ``False`` and :data:`.unset` if the member was not found in any form

    """
    for klass in cls.__mro__:
        namespace: dict[str, Any] = klass.__dict__
        if attrname in namespace:
            attribute = namespace[attrname]
            if isinstance(attribute, (classmethod, staticmethod)):
                # these are accessible on the class object itself
                return True, getattr(cls, attrname)
            elif hasattr(type(attribute), "__get__"):
                # instance level descriptors (functions, properties and attributes
                # defined in __slots__) only provide their values on the instances
                return True, unset
            else:
                return True, attribute

        # members which have only been annotated (in the class body, or in any of the
        # base classes, including the protocol itself when subclassed) are only
        # available on the instances of the class
        if attrname in namespace.get("__annotations__", ()):
            return True, unset

    # the member may still be provided by the metaclass
    try:
        return True, getattr(cls, attrname)
    except AttributeError:
        return False, unset


