import tomlkit
from tomlkit import dumps, parse


def show(label, fn):
    print("=" * 10, label)
    try:
        print(repr(fn()))
    except Exception as e:  # noqa
        print("ERROR", type(e).__name__, e)


def case1():
    v = parse("[x]\na.b = {}")
    v["x"]["c"] = 3
    return dumps(v)


def case2():
    v = parse("a.b = {}")
    v["c"] = 3
    return dumps(v)


def case3():
    v = parse("[[x]]\na.b = {}")
    v["x"][0]["c"] = 3
    return dumps(v)


def case4():
    v = parse("[x]\n[y]\na.b = {}")
    v["x"]["y"]["c"] = 3
    return dumps(v)


def case5():
    v = parse("[x]\na.b = {}\n")
    v["x"]["c"] = 3
    return dumps(v)


def case6():
    v = parse("[x]\na.b.c = {}")
    v["x"]["c"] = 3
    return dumps(v)


def case7():
    v = parse("[x]\na.b = {}")
    v["x"].add(tomlkit.comment("# hi"))
    return dumps(v)


def case8():
    v = parse("[x]\na.b = {}")
    v["x"].add(tomlkit.nl())
    v["x"]["c"] = 3
    return dumps(v)


def case9():
    v = parse("[x]\na.b = {}\n\n[y]\nz = 1")
    v["x"]["c"] = 3
    return dumps(v)


def case10():
    v = parse("[x]\na.b = {}\n")
    v["x"].add("d", 4)
    return dumps(v)


def case11():
    v = parse("[x]\na.b = {}\n")
    v["x"].append("d", 4)
    return dumps(v)


def case12():
    v = parse("[x]\na.b = 1\n[m]\nq = 1")
    v["x"]["c"] = 3
    return dumps(v)


def case13():
    v = parse("[x]\na.b = 1\n[m]\nq = 1")
    v["m"].add("c", 3)
    return dumps(v)


def case14():
    v = parse('[[a]]\nb.c = 1\n\n[[a]]\nb.d = 2\n')
    v["a"][1]["e"] = 3
    return dumps(v)


def case15():
    v = parse("[x]\na.b = 1")
    v["x"]["c"] = tomlkit.inline_table()
    v["x"]["c"]["z"] = 1
    return dumps(v)


def case16():
    v = parse("[x]\na.b = {}\n")
    del v["x"]["a"]
    v["x"]["c"] = 3
    return dumps(v)


for name, fn in sorted(globals().items()):
    if name.startswith("case"):
        show(name, fn)

