def _renders_table_header(it: Any) -> bool:
    """Whether ``it`` renders at least one ``[table]``/``[[array of tables]]`` header.

    Values that render inline (``key = value``, inline tables, super tables whose
    whole subtree is inline) don't, and neither does an empty ``AoT``, which has
    no element to build a ``[[header]]`` from.
    """
    if isinstance(it, AoT):
        return len(it) > 0

    if isinstance(it, Table):
        if not it.is_super_table():
            return True

        # A super table renders no header of its own, but its children might.
        return any(
            _renders_table_header(child) for _, child in it.value.body
        )

    return False


